-- Data Rule com valor fixo: publisher_id sempre será 42 no CREATE.
CREATE DATA RULE publisher_only
  APPLY publisher_id = 42;

-- Data Rule com valor do token: tenant_id será o id do usuário autenticado.
CREATE DATA RULE tenant_only
  APPLY tenant_id = $auth.id;

-- Usuário com data rule faz CREATE sem informar o campo:
CREATE article CONTENT { title: "Novo" };
-- Registro gravado: { id: article:xxx, title: "Novo", publisher_id: 42 }

-- Valor enviado pelo usuário é sobrescrito:
CREATE article CONTENT { title: "Burla", publisher_id: 99 };
-- Registro gravado: publisher_id = 42

-- SELECT, UPDATE e DELETE apenas filtram pelos campos da regra:
SELECT * FROM article;   -- WHERE publisher_id = 42
DELETE article;          -- remove apenas registros com publisher_id = 42

