  // recusa timestamps antigos ou futuros (proteção contra repetição)
  const age = Math.abs(Date.now() / 1000 - Number(timestamp));
  if (!Number.isFinite(age) || age > TOLERANCE_SECONDS) return res.sendStatus(401);

  // a assinatura cobre "timestamp.corpo"
  const expected =
    "sha256=" +
    crypto
      .createHmac("sha256", process.env.AXON_WEBHOOK_SECRET)
      .update(Buffer.concat([Buffer.from(timestamp + "."), req.body]))
      .digest("hex");

  const valid =
    received.length === expected.length &&
    crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));
  if (!valid) return res.sendStatus(401);

  const event = JSON.parse(req.body.toString("utf8"));
  console.log(event.type, event.data);
  res.sendStatus(204);
});

app.listen(9000);

